function makeBucket(rate, cap) {
  let tokens = cap;
  return {
    tick(seconds) { tokens = Math.min(cap, tokens + rate * seconds); },
    allow(n = 1) { if (tokens >= n) { tokens -= n; return true; } return false; },
    left() { return tokens; }
  };
}
const b = makeBucket(2, 5);
console.log("初始允许3? " + b.allow(3));
console.log("再允许4? " + b.allow(4));
b.tick(1);
console.log("tick1s后允许4? " + b.allow(4));
b.tick(10);
console.log("tick10s后剩余(上限5): " + b.left());
